  l  tile=carpet_10 door=escalator
  m  tile=carpet_11 object=rail_i
  n  tile=carpet_01 object=desk
  o  tile=carpet_11 object=desk
  p  tile=carpet_10 npc=vertice id=t2a face=S trainer=vertice_t2a range=4 text=tr.vertice_t2a.pre after=tr.vertice_t2a.after
  q  tile=carpet_10 object=rail_i
  r  tile=carpet_11 object=planter
  s  tile=carpet_01 npc=cientifico id=t2b face=W trainer=cientifico_t2a range=4 text=tr.cientifico_t2a.pre after=tr.cientifico_t2a.after
  t  tile=carpet_00 object=planter
